#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Run from the repo root so .env, deploy/ and .railway/ resolve.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
export COREPACK_ENABLE_DOWNLOAD_PROMPT=0

# ── Helpers for this wizard ───────────────────────────────────────────────
# The same pinned tools deploy/setup.sh uses.
node24() {
  if [[ "$(node --version 2>/dev/null)" == v24.* ]]; then "$@"
  elif command -v mise >/dev/null 2>&1; then mise exec node@24 -- "$@"
  else "$@"; fi
}
pnpm_() { node24 corepack pnpm "$@"; }
railway_() { node24 npx -y @railway/cli@5.71.0 "$@"; }
aws_() { aws --profile "$AWS_PROFILE" --region "$AWS_DEFAULT_REGION" "$@"; }
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
die() { warn "$1"; exit 1; }
# set_env_secret NAME VALUE sets a secret in the aws environment, from stdin.
set_env_secret() {
  printf '%s' "$2" | gh secret set "$1" --env aws --repo "$REPO" >/dev/null
  WRITTEN_SECRET+=("$1 (aws environment)")
  ok "set GitHub secret $1 in the aws environment"
}

# What going public publishes: every branch and tag on GitHub (fetched fresh, so
# merge-commit content and branches this checkout lacks are included), plus PR
# text and Actions artifacts.
PUBLISHED=(--remotes=origin --tags)

# build_scan_dump writes every version of every published file, commit
# messages, and PR titles, bodies and comments to $SCAN_DUMP, and counts
# Actions artifacts. Run it outside `if`, so a failed read stops the wizard
# instead of leaving a partial scan that looks clean.
build_scan_dump() {
  git fetch --quiet --prune --tags origin '+refs/heads/*:refs/remotes/origin/*'
  SCAN_DUMP=$(mktemp); chmod 600 "$SCAN_DUMP"
  # -m includes paths that only a merge commit added; quotePath=false keeps
  # non-ASCII paths unquoted so the filters below match them.
  SCAN_PATHS=$(git -c core.quotePath=false log "${PUBLISHED[@]}" -m --name-only --pretty=format: | sort -u)
  {
    git rev-list --objects "${PUBLISHED[@]}" | git cat-file --batch-check='%(objecttype) %(objectname)' \
      | awk '$1 == "blob" { print $2 }' | git cat-file --batch
    git log "${PUBLISHED[@]}" --format='%B'
    gh pr list --repo "$REPO" --state all --limit 500 --json title,body,comments,reviews \
      --jq '.[] | .title, .body, (.comments[].body), (.reviews[].body)'
    gh api --paginate "repos/$REPO/pulls/comments" --jq '.[].body'
  } > "$SCAN_DUMP"
  ARTIFACTS=$(gh api "repos/$REPO/actions/artifacts?per_page=1" --jq .total_count)
  RUNS=$(gh api "repos/$REPO/actions/runs?per_page=1" --jq .total_count)
}

# scan_history reports anything in $SCAN_DUMP that shouldn't be public: files
# that hold data or credentials, strings shaped like keys or tokens, the
# literal values in .env and the AWS account ID, and any Actions artifacts. It
# prints what kind of thing it found, never the value. Commit author lines are
# left out: your commit email is already public on GitHub.
scan_history() {
  local dump="$SCAN_DUMP" found=0 key value hits

  hits=$(grep -v '\.env\.example$' <<<"$SCAN_PATHS" \
    | grep -E '(^|/)\.env(\.|$)|(^|/)data(-demo|-ci)?/|(^|/)secrets/|\.duckdb(\.wal)?$|\.jsonl\.gz$|\.pem$' || true)
  if [[ -n "$hits" ]]; then
    warn "these files were committed at some point:"; note "$hits"; found=1
  fi

  hits=$(grep -aoE 'sk_(live|test)_[A-Za-z0-9]{20,}|pk_live_[A-Za-z0-9]{20,}|mnzconf\.?[A-Za-z0-9+/=]{16,}|oauth2client_[A-Za-z0-9]{12,}|(AKIA|ASIA)[0-9A-Z]{16}|eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}' "$dump" \
    | sed -E 's/^(.{8}).*/\1…/' | sort -u || true)
  if [[ -n "$hits" ]]; then
    warn "strings shaped like keys or tokens (first 8 characters shown):"; note "$hits"; found=1
  fi

  # Values that are fine to publish, or too generic to search for, are skipped.
  while IFS='=' read -r key value; do
    [[ "$key" =~ ^[A-Z_]+$ ]] || continue
    case "$key" in AWS_PROFILE|AWS_DEFAULT_REGION|DUCKBILL_DATA_DIR|MONZO_REDIRECT_URI|DUCKBILL_STORAGE_URI|DUCKBILL_TOKEN_PARAMETER) continue ;; esac
    value=$(_existing "$key" || true)
    (( ${#value} >= 8 )) || continue
    if grep -aqF -- "$value" "$dump"; then warn "the value of $key (from .env) appears"; found=1; fi
  done < "$ENV_FILE"
  if grep -aqwF -- "$ACCOUNT" "$dump"; then warn "your AWS account ID ($ACCOUNT) appears"; found=1; fi
  if (( ARTIFACTS > 0 )); then
    warn "$ARTIFACTS Actions artifact(s) would become downloadable: delete them first"; found=1
  fi

  rm -f "$dump"
  return "$found"
}

banner "duckbill: go public, protect main, deploy from GitHub"

# ──────────────────────────────────────────────────────────────────────────
stage "Check your tools and checkout"
say "This needs the PR that adds .github/workflows/ merged into main, and runs"
say "from main: Railway and CDK both apply the files in this checkout."
missing=()
for tool in git gh aws jq; do command -v "$tool" >/dev/null 2>&1 || missing+=("$tool"); done
node24 node --version 2>/dev/null | grep -q '^v24\.' || missing+=("Node 24 (mise install)")
(( ${#missing[@]} == 0 )) || die "missing: ${missing[*]}"
gh auth status >/dev/null 2>&1 || die "gh isn't signed in: run gh auth login"
[[ -f "$ENV_FILE" ]] || die "no $ENV_FILE here: run this from the checkout you deployed from with deploy/setup.sh"
REPO=$(git remote get-url origin | sed -E 's#^(git@github.com:|https://github.com/)##; s#\.git$##')
git fetch --quiet origin main
git cat-file -e origin/main:.github/workflows/deploy-aws.yml 2>/dev/null \
  || die "main on GitHub has no .github/workflows/deploy-aws.yml yet: merge that PR first."
[[ "$(git branch --show-current)" == main ]] || die "you're on $(git branch --show-current): git switch main"
if [[ "$(git rev-parse HEAD)" != "$(git rev-parse origin/main)" ]]; then
  confirm "main here isn't origin/main. Fast-forward it (git pull --ff-only)?" || exit 1
  git pull --ff-only --quiet
fi
[[ -z "$(git status --porcelain)" ]] || die "uncommitted changes here would be deployed: commit or stash them first"
step "Installing Node dependencies from the lockfile..."
pnpm_ install --frozen-lockfile >/dev/null
ask AWS_PROFILE "AWS profile:"
ask AWS_DEFAULT_REGION "AWS region:"
export AWS_PROFILE AWS_DEFAULT_REGION AWS_REGION="$AWS_DEFAULT_REGION"
identity=$(aws_ sts get-caller-identity --query '[Account, Arn]' --output text 2>&1) \
  || die "can't use profile $AWS_PROFILE: $identity (for SSO: aws sso login --profile $AWS_PROFILE)"
ACCOUNT=${identity%%[[:space:]]*}
ok "GitHub repo $REPO, AWS account $ACCOUNT ($AWS_DEFAULT_REGION)"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Last check before going public"
say "Making $REPO public publishes every commit on every branch, every PR and"
say "comment, and from then on every Actions log. Scanning all of it for data,"
say "keys, and the values in $ENV_FILE..."
build_scan_dump
if scan_history; then
  ok "nothing found in $(git rev-list --count "${PUBLISHED[@]}") commits on $(git branch -r | grep -vc HEAD) branches, or in PR text"
else
  die "fix the findings above (rewrite history or delete the branch) before going public"
fi
note "$RUNS Actions run(s) so far; their logs go public too. CI only ever sees demo data."
note "Your commit email is in some commits' author lines, as in your other public repos."
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Make the repository public"
if [[ "$(gh repo view "$REPO" --json visibility -q .visibility)" == PUBLIC ]]; then
  ok "$REPO is already public"
else
  warn "anyone will be able to read and fork it. Making it private again later"
  warn "doesn't recall forks or clones."
  confirm "Make $REPO public?" || exit 1
  gh repo edit "$REPO" --visibility public --accept-visibility-change-consequences
  ok "$REPO is public"
fi
# Free on public repos: GitHub scans every push for keys, and push protection
# rejects a push that contains one.
jq -n '{security_and_analysis: {secret_scanning: {status: "enabled"},
  secret_scanning_push_protection: {status: "enabled"}}}' \
  | gh api -X PATCH "repos/$REPO" --input - >/dev/null
ok "secret scanning and push protection are on"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Protect main"
say "A rule so main only changes through a pull request whose CI checks pass and"
say "that is up to date with main. Railway deploys every commit on main, and"
say "Deploy AWS ships main, so this keeps unchecked code out of both."
# The job names in .github/workflows/ci.yml.
CHECKS='["Checks", "Images"]'
ruleset=$(gh api "repos/$REPO/rulesets" --jq '.[] | select(.name == "main") | .id' 2>/dev/null || true)
if [[ -n "$ruleset" ]]; then
  gh api "repos/$REPO/rulesets/$ruleset" | jq -e --argjson checks "$CHECKS" '
    .enforcement == "active" and .target == "branch"
    and (.conditions.ref_name.include | index("~DEFAULT_BRANCH") or index("refs/heads/main"))
    and (.conditions.ref_name.exclude // []) == [] and (.bypass_actors // []) == []
    and any(.rules[]; .type == "pull_request")
    and any(.rules[]; .type == "required_status_checks"
            and .parameters.strict_required_status_checks_policy == true
            and ($checks - [.parameters.required_status_checks[].context] == []))' >/dev/null \
    || die "ruleset $ruleset (main) must be active on main, with no exclusions or bypasses, and require PRs and the checks $CHECKS, up to date with main. Fix or delete it (Settings → Rules), then re-run."
  ok "main is already protected (ruleset $ruleset)"
elif confirm "Protect main with the required CI checks?"; then
  jq -n --argjson checks "$CHECKS" '{
    name: "main", target: "branch", enforcement: "active",
    conditions: { ref_name: { include: ["~DEFAULT_BRANCH"], exclude: [] } },
    rules: [
      { type: "deletion" },
      { type: "non_fast_forward" },
      { type: "pull_request", parameters: {
          required_approving_review_count: 0, dismiss_stale_reviews_on_push: false,
          require_code_owner_review: false, require_last_push_approval: false,
          required_review_thread_resolution: false } },
      { type: "required_status_checks", parameters: {
          strict_required_status_checks_policy: true,
          required_status_checks: [$checks[] | { context: . }] } }
    ] }' | gh api "repos/$REPO/rulesets" -X POST --input - >/dev/null
  ok "main now needs a pull request with passing checks"
else
  die "GitHub deploys whatever is on main, so main must be protected first. Re-run when ready."
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "GitHub: the aws environment"
say "Deploy AWS runs in an environment called aws that only main may use. The AWS"
say "role trusts this environment, so it's set up and checked before the role exists."
jq -n '{deployment_branch_policy: {protected_branches: false, custom_branch_policies: true}}' \
  | gh api -X PUT "repos/$REPO/environments/aws" --input - >/dev/null
# The role trusts the environment, not the branch, so the environment's policy
# must be exactly the main branch.
env_policies() {
  gh api --paginate "repos/$REPO/environments/aws/deployment-branch-policies" \
    --jq '.branch_policies[] | "\(.type):\(.name)"' | sort | paste -sd ' ' -
}
policies=$(env_policies)
if [[ -z "$policies" ]]; then
  gh api -X POST "repos/$REPO/environments/aws/deployment-branch-policies" \
    -f name=main -f type=branch >/dev/null
  policies=$(env_policies)
fi
[[ "$policies" == "branch:main" ]] \
  || die "the aws environment allows: $policies. Leave only the main branch (Settings → Environments → aws), then re-run."
ok "environment aws, deployable from main only"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "AWS: the role GitHub deploys with"
say "Creates duckbill-github-deploy (deploy/cdk/lib/github.ts). Only the Deploy AWS"
say "workflow, running from main, can use it, and it holds no keys: GitHub signs"
say "in through AWS's OIDC trust. It can run cdk deploy and start the dbt function."
note "cdk deploy can change anything in the account, as it can from your machine,"
note "so main's ruleset (stage 4) is what keeps unreviewed code from deploying."
ask DUCKBILL_ALERT_EMAIL "Alarm email address (the one deploy/setup.sh used):"
owned=$(aws_ cloudformation list-stack-resources --stack-name DuckbillGithub \
  --query "StackResourceSummaries[?ResourceType=='AWS::IAM::OIDCProvider'].PhysicalResourceId" \
  --output text 2>/dev/null || true)
existing=$(aws_ iam list-open-id-connect-providers \
  --query "OpenIDConnectProviderList[?ends_with(Arn, '/token.actions.githubusercontent.com')].Arn" --output text)
provider_args=()
if [[ -n "$existing" && "$existing" != "$owned" ]]; then
  note "Reusing the GitHub OIDC provider already in this account."
  provider_args=(-c "githubOidcProviderArn=$existing")
fi
say "CDK shows the IAM changes before applying them; review and confirm."
(
  cd deploy/cdk
  pnpm_ exec cdk deploy DuckbillGithub -c "alertEmail=$DUCKBILL_ALERT_EMAIL" \
    -c "githubRepo=$REPO" "${provider_args[@]}" --require-approval broadening
) || die "the deploy failed; fix the error above and re-run"
ROLE_ARN=$(aws_ cloudformation describe-stacks --stack-name DuckbillGithub \
  --query "Stacks[0].Outputs[?OutputKey=='RoleArn'].OutputValue" --output text)
ok "role $ROLE_ARN"
say "Storing what Deploy AWS needs in the aws environment. Only jobs in it can"
say "read these secrets, and GitHub masks them in logs."
set_env_secret AWS_DEPLOY_ROLE_ARN "$ROLE_ARN"
set_env_secret ALERT_EMAIL "$DUCKBILL_ALERT_EMAIL"
gh variable set AWS_REGION --env aws --repo "$REPO" --body "$AWS_DEFAULT_REGION" >/dev/null
ok "set GitHub variable AWS_REGION in the aws environment"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Railway: wait for CI"
say "Applies .railway/railway.ts, which now turns on Railway's Wait for CI: a"
say "commit on main deploys the dashboard only once its CI checks pass."
railway_ whoami >/dev/null 2>&1 || railway_ login
railway_ status >/dev/null 2>&1 || die "this checkout isn't linked to the Railway project: run railway link"
say "Review the plan (it should only change the source's check suites), then confirm."
railway_ config apply
pause

# ──────────────────────────────────────────────────────────────────────────
stage "First deploy from GitHub"
say "Runs Deploy AWS on main. It ships what's merged (the budget, and the"
say "publish check that refuses to lose transactions), then rebuilds the dashboard"
say "once. It never runs the ingest function, so the Monzo token isn't touched."
note "About 10 minutes. Later deploys: Actions → Deploy AWS → Run workflow."
if confirm "Run Deploy AWS now?"; then
  started=$(date -u +%Y-%m-%dT%H:%M:%SZ)
  gh workflow run deploy-aws.yml --repo "$REPO" --ref main
  run_id=""
  for _ in $(seq 1 30); do
    run_id=$(gh run list --repo "$REPO" --workflow deploy-aws.yml --event workflow_dispatch --limit 5 \
      --json databaseId,createdAt --jq "[.[] | select(.createdAt >= \"$started\")][0].databaseId // empty")
    [[ -n "$run_id" ]] && break
    sleep 2
  done
  [[ -n "$run_id" ]] || die "couldn't find the run; watch it in the Actions tab"
  if gh run watch "$run_id" --repo "$REPO" --exit-status; then
    ok "deployed from GitHub"
  else
    warn "the deploy failed: gh run view $run_id --repo $REPO --log-failed"
    SKIPPED+=("Re-run Deploy AWS once the failure is fixed")
  fi
else
  SKIPPED+=("Run Deploy AWS: Actions → Deploy AWS → Run workflow")
